import sys
input = sys.stdin.read
data = input().split()

index = 0
T = int(data[index])
index += 1

results = []

for _ in range(T):
    Q = int(data[index])
    index += 1

    S = set()
    even_count = 0
    odd_count = 0

    for _ in range(Q):
        X = int(data[index])
        index += 1

        if X not in S:
            S.add(X)

            if bin(X).count('1') % 2 == 0:
                even_count += 1
            else:
                odd_count += 1

            for y in list(S):
                if y != X:
                    new_element = y ^ X
                    if new_element not in S:
                        S.add(new_element)

                        if bin(new_element).count('1') % 2 == 0:
                            even_count += 1
                        else:
                            odd_count += 1

        results.append(f"{even_count} {odd_count}")

print("\n".join(results))
